create schema if not exists private;
revoke all on schema private from public, anon, authenticated;
grant usage on schema private to authenticated;
create table if not exists private.site_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
alter table private.site_admins enable row level security;
revoke all on private.site_admins from public,anon,authenticated;
create or replace function private.is_site_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from private.site_admins a where a.user_id=(select auth.uid())); $$;
revoke all on function private.is_site_admin() from public,anon;
grant execute on function private.is_site_admin() to authenticated;
create table if not exists public.videos(id uuid primary key default gen_random_uuid(),title text not null check(char_length(btrim(title)) between 1 and 120),description text not null default '' check(char_length(description)<=2000),provider text not null check(provider in('youtube','vimeo')),source_url text not null check(source_url ~ '^https://'),embed_url text not null,thumbnail_url text check(thumbnail_url is null or thumbnail_url ~ '^https://'),status text not null default 'draft' check(status in('draft','published','rejected')),created_by uuid not null references auth.users(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),published_at timestamptz,constraint videos_embed_provider_check check((provider='youtube' and embed_url ~ '^https://www\\.youtube-nocookie\\.com/embed/[A-Za-z0-9_-]+$') or (provider='vimeo' and embed_url ~ '^https://player\\.vimeo\\.com/video/[0-9]+$')));
create index if not exists videos_public_feed_idx on public.videos(published_at desc,created_at desc) where status='published';
create index if not exists videos_created_by_idx on public.videos(created_by);
alter table public.videos enable row level security;
revoke all on public.videos from public,anon,authenticated;
grant select on public.videos to anon;
grant select,insert,update,delete on public.videos to authenticated;
create policy "Published videos are public" on public.videos for select to anon,authenticated using(status='published' or (select private.is_site_admin()));
create policy "Only site admin can insert videos" on public.videos for insert to authenticated with check((select private.is_site_admin()) and created_by=(select auth.uid()));
create policy "Only site admin can update videos" on public.videos for update to authenticated using((select private.is_site_admin())) with check((select private.is_site_admin()) and created_by=(select auth.uid()));
create policy "Only site admin can delete videos" on public.videos for delete to authenticated using((select private.is_site_admin()));
create or replace function public.set_video_updated_at() returns trigger language plpgsql set search_path='' as $$ begin new.updated_at=now(); if new.status='published' and old.status is distinct from 'published' then new.published_at=now(); elsif new.status<>'published' then new.published_at=null; end if; return new; end; $$;
revoke all on function public.set_video_updated_at() from public,anon,authenticated;
create trigger videos_set_updated_at before update on public.videos for each row execute function public.set_video_updated_at();
comment on table public.videos is 'Xcontent non-explicit prototype video link catalogue. No media files are uploaded.';
